            defaultValue: '0'
        },
        {
            key: 'info',
            label: '完整简介',
            defaultValue: 'on'
        }
    ];

    var valueMap = {
        // 访问模式
        '本地': '💻 本地',
        '云端': '☁️ 云端',

        // 开关状态
        'on': '✅ 开启',
        'off': '❌ 关闭',
        '1': '✅ 开启',
        '0': '❌ 关闭',

        // 频道类型
        '男频': '👨 男频',
        '女频': '👩 女频',

        // 内容类型
        '小说': '📖 小说',
        '听书': '🎧 听书',
        '漫画': '🎨 漫画',
        '短剧': '🎬 短剧',

        // 来源类型
        'vip': '💎 VIP专属',
        'svip': '👑 SVIP专属',
        '推荐': '⭐ 网友推荐',
        '全部': '📚 全部'
    };


    var displayLines = [];

    for (var i = 0; i < displayConfig.length; i++) {
        var config = displayConfig[i];
        var value = cookieData[config.key] || getArgument(config.key) || config.defaultValue;


        if (!cookieData[config.key]) {
            setArgument(config.key, config.defaultValue);
        }

        var displayValue = valueMap[value] || value;
        if (config.key === 'sources' && displayValue.length > 25) {
            displayValue = displayValue.substring(0, 25) + '...';
        }

        displayLines.push(config.label + ': ' + displayValue);
    }

    // 构建提示模板
    var template = '✨ 当前配置\n';
    template += '━━━━━━━━━━━━━━━━\n';
